-- Booking email templates as editable HTML, stored in the DB (single source).
-- Shape: { customer|business: { <kind>: { <locale>: { subject, html } } } }.
-- The html/subject are raw strings with {{variables}} the edge function injects
-- at send time: {{business}}, {{business_avatar}} (business logo/avatar img or a
-- lettered fallback), {{brand_primary}}/{{brand_accent}}/{{brand_background}}
-- (the business's own brand colours from profiles.brand_colors), {{customer_name}},
-- {{customer_first_name}}, {{service}}, {{staff}}, {{date_time}}, {{price}},
-- {{manage_url}}. The Nandzz logo in the footer is a static asset URL. Edit via
-- the nandzz-admin "Email templates" page. Replaces the earlier structured-config
-- seed (different shape) — safe because the feature isn't in real use yet.
insert into public.app_settings (key, value, description)
values (
  'booking_email_template',
  $tpl${"customer":{"confirmation":{"en":{"subject":"Booking confirmed — {{service}}","html":"<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n<meta name=\"color-scheme\" content=\"light only\" />\n</head>\n<body style=\"margin:0;padding:0;background:#f4f4f5\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;background:#f4f4f5\">\n  <tr><td align=\"center\" style=\"padding:28px 12px\">\n    <table role=\"presentation\" width=\"560\" cellpadding=\"0\" cellspacing=\"0\"\n      style=\"border-collapse:collapse;width:560px;max-width:100%;background:#ffffff;border:1px solid #e9eaec;border-radius:14px;overflow:hidden\">\n      <!-- Header -->\n      <tr><td style=\"padding:22px 24px 8px\">\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\">\n          <tr>\n            <td valign=\"middle\" style=\"padding-right:12px\">{{business_avatar}}</td>\n            <td valign=\"middle\" style=\"font:700 17px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{business}}</td>\n          </tr>\n        </table>\n      </td></tr>\n      <!-- Body -->\n      <tr><td style=\"padding:8px 24px 4px\">\n        <div style=\"font:700 21px/1.3 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827;margin:6px 0 10px\">You&#39;re booked!</div>\n        <div style=\"font:400 15px/1.6 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#374151\">Hi {{customer_first_name}}, your booking with {{business}} is confirmed. We look forward to seeing you.</div>\n        <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"\n    style=\"border-collapse:collapse;background:#f9fafb;border:1px solid #eef0f2;border-radius:10px;margin:8px 0 4px\">\n    <tr><td style=\"padding:14px 18px 2px\">\n      <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\"><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Service</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{service}}</td>\n      </tr><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Date &amp; time</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{date_time}}</td>\n      </tr><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">With</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{staff}}</td>\n      </tr><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Price</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{price}}</td>\n      </tr></table>\n    </td></tr></table>\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;margin:20px 0 4px\">\n    <tr><td align=\"center\" style=\"border-radius:8px;background:{{brand_primary}}\">\n      <a href=\"{{manage_url}}\" target=\"_blank\"\n        style=\"display:inline-block;padding:12px 22px;font:600 15px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#ffffff;text-decoration:none;border-radius:8px\">\n        Manage booking</a>\n    </td></tr></table>\n      </td></tr>\n      <!-- Footer -->\n      <tr><td style=\"padding:20px 24px 24px\">\n        <div style=\"border-top:1px solid #eef0f2;padding-top:14px\">\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\">\n            <tr>\n              <td valign=\"middle\" style=\"padding-right:6px;font:400 12px/1.5 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af\">Powered by</td>\n              <td valign=\"middle\"><img src=\"https://nandzz.com/logo.png\" width=\"18\" height=\"19\" alt=\"Nandzz\" style=\"display:block;border:0\" /></td>\n            </tr>\n          </table>\n        </div>\n      </td></tr>\n    </table>\n  </td></tr>\n</table>\n</body></html>"},"pt":{"subject":"Reserva confirmada — {{service}}","html":"<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n<meta name=\"color-scheme\" content=\"light only\" />\n</head>\n<body style=\"margin:0;padding:0;background:#f4f4f5\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;background:#f4f4f5\">\n  <tr><td align=\"center\" style=\"padding:28px 12px\">\n    <table role=\"presentation\" width=\"560\" cellpadding=\"0\" cellspacing=\"0\"\n      style=\"border-collapse:collapse;width:560px;max-width:100%;background:#ffffff;border:1px solid #e9eaec;border-radius:14px;overflow:hidden\">\n      <!-- Header -->\n      <tr><td style=\"padding:22px 24px 8px\">\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\">\n          <tr>\n            <td valign=\"middle\" style=\"padding-right:12px\">{{business_avatar}}</td>\n            <td valign=\"middle\" style=\"font:700 17px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{business}}</td>\n          </tr>\n        </table>\n      </td></tr>\n      <!-- Body -->\n      <tr><td style=\"padding:8px 24px 4px\">\n        <div style=\"font:700 21px/1.3 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827;margin:6px 0 10px\">Reserva confirmada!</div>\n        <div style=\"font:400 15px/1.6 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#374151\">Olá {{customer_first_name}}, sua reserva com {{business}} está confirmada. Esperamos por você.</div>\n        <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"\n    style=\"border-collapse:collapse;background:#f9fafb;border:1px solid #eef0f2;border-radius:10px;margin:8px 0 4px\">\n    <tr><td style=\"padding:14px 18px 2px\">\n      <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\"><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Serviço</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{service}}</td>\n      </tr><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Data e hora</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{date_time}}</td>\n      </tr><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Com</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{staff}}</td>\n      </tr><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Preço</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{price}}</td>\n      </tr></table>\n    </td></tr></table>\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;margin:20px 0 4px\">\n    <tr><td align=\"center\" style=\"border-radius:8px;background:{{brand_primary}}\">\n      <a href=\"{{manage_url}}\" target=\"_blank\"\n        style=\"display:inline-block;padding:12px 22px;font:600 15px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#ffffff;text-decoration:none;border-radius:8px\">\n        Gerenciar reserva</a>\n    </td></tr></table>\n      </td></tr>\n      <!-- Footer -->\n      <tr><td style=\"padding:20px 24px 24px\">\n        <div style=\"border-top:1px solid #eef0f2;padding-top:14px\">\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\">\n            <tr>\n              <td valign=\"middle\" style=\"padding-right:6px;font:400 12px/1.5 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af\">Desenvolvido por</td>\n              <td valign=\"middle\"><img src=\"https://nandzz.com/logo.png\" width=\"18\" height=\"19\" alt=\"Nandzz\" style=\"display:block;border:0\" /></td>\n            </tr>\n          </table>\n        </div>\n      </td></tr>\n    </table>\n  </td></tr>\n</table>\n</body></html>"},"fr":{"subject":"Réservation confirmée — {{service}}","html":"<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n<meta name=\"color-scheme\" content=\"light only\" />\n</head>\n<body style=\"margin:0;padding:0;background:#f4f4f5\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;background:#f4f4f5\">\n  <tr><td align=\"center\" style=\"padding:28px 12px\">\n    <table role=\"presentation\" width=\"560\" cellpadding=\"0\" cellspacing=\"0\"\n      style=\"border-collapse:collapse;width:560px;max-width:100%;background:#ffffff;border:1px solid #e9eaec;border-radius:14px;overflow:hidden\">\n      <!-- Header -->\n      <tr><td style=\"padding:22px 24px 8px\">\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\">\n          <tr>\n            <td valign=\"middle\" style=\"padding-right:12px\">{{business_avatar}}</td>\n            <td valign=\"middle\" style=\"font:700 17px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{business}}</td>\n          </tr>\n        </table>\n      </td></tr>\n      <!-- Body -->\n      <tr><td style=\"padding:8px 24px 4px\">\n        <div style=\"font:700 21px/1.3 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827;margin:6px 0 10px\">C&#39;est réservé !</div>\n        <div style=\"font:400 15px/1.6 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#374151\">Bonjour {{customer_first_name}}, votre réservation avec {{business}} est confirmée. Au plaisir de vous voir.</div>\n        <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"\n    style=\"border-collapse:collapse;background:#f9fafb;border:1px solid #eef0f2;border-radius:10px;margin:8px 0 4px\">\n    <tr><td style=\"padding:14px 18px 2px\">\n      <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\"><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Service</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{service}}</td>\n      </tr><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Date et heure</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{date_time}}</td>\n      </tr><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Avec</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{staff}}</td>\n      </tr><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Prix</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{price}}</td>\n      </tr></table>\n    </td></tr></table>\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;margin:20px 0 4px\">\n    <tr><td align=\"center\" style=\"border-radius:8px;background:{{brand_primary}}\">\n      <a href=\"{{manage_url}}\" target=\"_blank\"\n        style=\"display:inline-block;padding:12px 22px;font:600 15px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#ffffff;text-decoration:none;border-radius:8px\">\n        Gérer la réservation</a>\n    </td></tr></table>\n      </td></tr>\n      <!-- Footer -->\n      <tr><td style=\"padding:20px 24px 24px\">\n        <div style=\"border-top:1px solid #eef0f2;padding-top:14px\">\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\">\n            <tr>\n              <td valign=\"middle\" style=\"padding-right:6px;font:400 12px/1.5 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af\">Propulsé par</td>\n              <td valign=\"middle\"><img src=\"https://nandzz.com/logo.png\" width=\"18\" height=\"19\" alt=\"Nandzz\" style=\"display:block;border:0\" /></td>\n            </tr>\n          </table>\n        </div>\n      </td></tr>\n    </table>\n  </td></tr>\n</table>\n</body></html>"},"es":{"subject":"Reserva confirmada — {{service}}","html":"<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n<meta name=\"color-scheme\" content=\"light only\" />\n</head>\n<body style=\"margin:0;padding:0;background:#f4f4f5\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse;background:#f4f4f5\">\n  <tr><td align=\"center\" style=\"padding:28px 12px\">\n    <table role=\"presentation\" width=\"560\" cellpadding=\"0\" cellspacing=\"0\"\n      style=\"border-collapse:collapse;width:560px;max-width:100%;background:#ffffff;border:1px solid #e9eaec;border-radius:14px;overflow:hidden\">\n      <!-- Header -->\n      <tr><td style=\"padding:22px 24px 8px\">\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\">\n          <tr>\n            <td valign=\"middle\" style=\"padding-right:12px\">{{business_avatar}}</td>\n            <td valign=\"middle\" style=\"font:700 17px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{business}}</td>\n          </tr>\n        </table>\n      </td></tr>\n      <!-- Body -->\n      <tr><td style=\"padding:8px 24px 4px\">\n        <div style=\"font:700 21px/1.3 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827;margin:6px 0 10px\">¡Reserva confirmada!</div>\n        <div style=\"font:400 15px/1.6 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#374151\">Hola {{customer_first_name}}, tu reserva con {{business}} está confirmada. Te esperamos.</div>\n        <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"\n    style=\"border-collapse:collapse;background:#f9fafb;border:1px solid #eef0f2;border-radius:10px;margin:8px 0 4px\">\n    <tr><td style=\"padding:14px 18px 2px\">\n      <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\"><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Servicio</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{service}}</td>\n      </tr><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Fecha y hora</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{date_time}}</td>\n      </tr><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Con</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827\">{{staff}}</td>\n      </tr><tr>\n        <td style=\"padding:6px 0;font:400 12px/1.4 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.04em\">Precio</td>\n      </tr>\n      <tr>\n        <td style=\"padding:0 0 12px;font:600 15px/1