\" cellspacing=\"0\" style=\"border-collapse:collapse;margin:20px 0 4px\">\n    <tr><td align=\"center\" style=\"border-radius:8px;background:{{brand_primary}}\">\n      <a href=\"{{manage_url}}\" target=\"_blank\"\n        style=\"display:inline-block;padding:12px 22px;font:600 15px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#ffffff;text-decoration:none;border-radius:8px\">\n        Gestisci prenotazione</a>\n    </td></tr></table>\n      </td></tr>\n      <!-- Footer -->\n      <tr><td style=\"padding:20px 24px 24px\">\n        <div style=\"border-top:1px solid #eef0f2;padding-top:14px\">\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse\">\n            <tr>\n              <td valign=\"middle\" style=\"padding-right:6px;font:400 12px/1.5 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#9ca3af\">Offerto da</td>\n              <td valign=\"middle\"><img src=\"https://nandzz.com/logo.png\" width=\"18\" height=\"19\" alt=\"Nandzz\" style=\"display:block;border:0\" /></td>\n            </tr>\n          </table>\n        </div>\n      </td></tr>\n    </table>\n  </td></tr>\n</table>\n</body></html>"}}}}
$tpl$::jsonb,
  'Booking email HTML templates (subject + html per type/locale, with {{variables}}). Authoritative source read by the booking-notifications edge function; edit via the nandzz-admin Email templates page.'
)
on conflict (key) do update
  set value = excluded.value,
      description = excluded.description,
      updated_at = now();
